import Image from "next/image"
import React, { useState } from "react"

const Wishlist = () => {
  const [wishlist,setIsWishlist] = useState()
  return (
    <div className="bg-gray-400 size-8 flex items-center justify-center rounded-full">
      <button className="size-6">
        <Image
          src="/images/icon/heart-icon.svg"
          width={1000}
          height={1000}
          alt="not found"
        />
      </button>
    </div>
  )
}

export default Wishlist
