import Location from "@/components/atoms/location"
import Wishlist from "@/components/atoms/wishlist/indes"
import SuperPower from "@/components/molecules/superPower"
import { cn } from "@/lib/utils"
import Image from "next/image"
import React from "react"

const Card = ({
  borderColor,
  cardData,
  cardStyle,
  imageContainerStyle,
  rounded,
  supercoin,
  superPower,
}) => {
  return (
    <>
      {cardData.map((item, index) => (
        <div
          key={index}
          className={cn(
            "border p-4 overflow-hidden relative",
            borderColor ? borderColor : "border-gray-400",
            cardStyle,
            rounded ? rounded : "rounded-xl",
            supercoin && "flex flex-col"
          )}>
          {/* Image Section  */}
          <div className="relative">
            <div className={cn(imageContainerStyle ? imageContainerStyle : "aspect-[4/3] h-[222px]")}>
              <Image
                src={item.image}
                width={1000}
                height={1000}
                alt="not found"
                className="w-full h-full object-cover"
              />
            </div>

            {/* Super Power  */}
            {superPower && <SuperPower />}
            <Wishlist />
          </div>

          {/* Card Content  */}
          <div className="p-4 flex flex-col justify-between flex-grow">
            <div>
              <p className="text-lg font-semibold line-clamp-2 text-ellipsis">{item.title}</p>
              <Location
                city={item.city}
                day={item.day}
                dotted
              />
            </div>
            {/* Pricing  */}
            <div className="flex items-center justify-between mt-3">
              <div>
                <p className="font-semibold text-lg">₹ {item.price}</p>
                <p className="text-gray-400 text-sm">Per Person Onwards</p>
              </div>
              <button className="bg-orange-600 text-white rounded-full px-5 py-2 font-semibold border border-orange-600 hover:bg-white hover:text-orange-600 transition-all duration-300">Discover</button>
            </div>
          </div>
          {supercoin &&
            <div className="bg-green-800 flex items-center justify-center gap-2 h-[33px]">
              <Image
                src="/images/supercoin-icon2.svg"
                width={16}
                height={16}
                alt="not found"
              />
              <span className="text-white text-center block">Supercoin</span>
            </div>}
        </div>
      ))}

    </>
  )
}

export default Card
